"""A single function: the smallest thing PyArmor can protect."""


def apply_discount(price: float, loyalty_years: int) -> float:
    """Loyal customers get 2% off per year, capped at 10%."""
    discount = min(loyalty_years * 0.02, 0.10)
    return round(price * (1 - discount), 2)

"""Pricing rules: the kind of logic a company would rather not publish."""

BASE_MARGIN = 0.32
VOLUME_BREAKS = ((1000, 0.05), (500, 0.03), (100, 0.01))


def quote(unit_cost: float, quantity: int, priority: bool = False) -> float:
    """Price an order: cost plus margin, minus volume discounts, plus a rush fee."""
    price = unit_cost * (1 + BASE_MARGIN) * quantity
    for threshold, discount in VOLUME_BREAKS:
        if quantity >= threshold:
            price *= 1 - discount
            break
    if priority:
        price *= 1.15
    return round(price, 2)

"""A class: methods, state and a classmethod, all protected together."""


class ChurnPredictor:
    """Flags customers likely to leave, from simple usage signals."""

    THRESHOLD = 0.6

    def __init__(self, weight_logins: float = 0.5, weight_tickets: float = 0.3) -> None:
        self.weight_logins = weight_logins
        self.weight_tickets = weight_tickets

    def risk(self, logins_last_30d: int, open_tickets: int) -> float:
        inactivity = max(0.0, 1 - logins_last_30d / 20)
        frustration = min(1.0, open_tickets / 5)
        return round(self.weight_logins * inactivity + self.weight_tickets * frustration, 3)

    def will_churn(self, logins_last_30d: int, open_tickets: int) -> bool:
        return self.risk(logins_last_30d, open_tickets) >= self.THRESHOLD

    @classmethod
    def strict(cls) -> "ChurnPredictor":
        return cls(weight_logins=0.7, weight_tickets=0.4)

"""A FastAPI endpoint. Routes are protected like any other module; the HTTP API stays the same."""

from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI()


class Order(BaseModel):
    amount: float = Field(gt=0)
    country: str = Field(min_length=2, max_length=2)


FRAUD_COUNTRIES = {"XX", "YY"}


@app.post("/score-order")
def score_order(order: Order) -> dict:
    """Return a fraud score for an order. The rules are the protected part."""
    score = 0.1
    if order.amount > 5000:
        score += 0.4
    if order.country.upper() in FRAUD_COUNTRIES:
        score += 0.3
    return {"fraud_score": round(min(score, 1.0), 2), "review": score >= 0.5}

"""The scoring model: the demo's main piece of "intellectual property".

Every weight and threshold below is a business decision. Readable source gives all of them away
in seconds, which is what the workshop protects with PyArmor and then examines honestly.
"""

# How much engaged customers reduce raw risk (0.35 = up to 35% less).
ENGAGEMENT_RISK_DAMPING = 0.35

# Weights of the business score. They are tuned so a perfect customer with no risk scores 100.
WEIGHTS = {"value": 0.55, "engagement": 0.45, "risk_penalty": 0.30}

# Lower bounds of each class, checked from the top down.
CLASS_THRESHOLDS = (
    (75.0, "strategic"),
    (55.0, "growth"),
    (35.0, "nurture"),
    (0.0, "watch"),
)


def _clamp(value: float, low: float = 0.0, high: float = 100.0) -> float:
    return max(low, min(high, value))


def calculate_risk_score(risk_factor: float, engagement: float) -> float:
    """Risk on 0..100. Engagement damps risk: an active customer is a safer customer."""
    raw = risk_factor * 100
    damped = raw * (1 - ENGAGEMENT_RISK_DAMPING * engagement)
    return round(_clamp(damped), 2)


def calculate_business_score(
    value_index: float, engagement_index: float, risk_score: float
) -> float:
    """Business score on 0..100 from the transformed features and the risk score."""
    positive = WEIGHTS["value"] * value_index + WEIGHTS["engagement"] * engagement_index
    penalty = WEIGHTS["risk_penalty"] * risk_score
    return round(_clamp(positive * 100 - penalty), 2)


def classify(score: float) -> str:
    """Name the band a business score falls in."""
    for threshold, label in CLASS_THRESHOLDS:
        if score >= threshold:
            return label
    return "watch"
